// Hinglish (Hindi in English letters, as showroom staff text each other) for the whole app: exact English text -> Hinglish,
// read by js/i18n.js while the Hinglish switch is on. Same keys as js/i18n-hi.js (the tests check that), same rules:
//  - "{}" is a value filled in at run time (a number, a name, an amount); keep it. When the order must change, number them: {1}, {2}.
//  - Trade and tech words stay English (lead, booking, RTO, follow-up, stock, deal, token ...); the rest is everyday Hinglish.
//  - A value equal to its key means "leave as it is" (brand names, units, acronyms).
// Add a missing string: run `python scripts/i18n_extract.py --missing`, add a line here AND in js/i18n-hi.js.
