"Leads nobody followed up go on a list for the approvers, who move them to another salesman, keep them or excuse them. Nothing moves without their OK.": "Jin leads pe kisi ne follow-up nahi kiya, wo approvers ki list mein jaate hain, jo unhe dusre salesman ko move karte hain, rakh lete hain ya maaf kar dete hain. Unke OK ke bina kuch nahi hilta.",
"leads per wave": "leads har batch mein",
"Leads received": "Mile leads",
"Leads still arrive; the time left will show again in a minute.": "Leads ab bhi aa rahe hain; bacha time ek minute mein phir dikhega.",
"Leads that came in after closing. Nobody holds them until opening; then they go out by price band and performance, a few at a time.": "Band hone ke baad aaye leads. Khulne tak inhe koi nahi rakhta; phir ye price band aur performance ke hisaab se thode-thode karke nikalte hain.",
"Leads that come in after closing wait here with no salesman. At opening they go out in waves, by price band and performance.": "Band hone ke baad aaye leads bina salesman ke yahan rukte hain. Khulne pe ye batch mein price band aur performance ke hisaab se bante hain.",
"Leads that come in after closing wait with no salesman, then go out at opening by price band and performance.": "Band hone ke baad aaye leads bina salesman ke ruke rehte hain, phir khulne pe price band aur performance ke hisaab se bante hain.",
"Leads that go on the follow-up list unless you follow up": "Wo leads jo follow-up nahi karne pe follow-up list mein chale jaate hain",
"Leads that go on the follow-up list unless you follow up. A call counts once its brief is filled.": "Wo leads jo follow-up nahi karne pe follow-up list mein chale jaate hain. Call tab gini jaati hai jab brief bhar diya ho.",
"Leads unclaimed for longer count as missed.": "Isse zyada der unclaimed rehne wale leads missed gine jaate hain.",
"Leads waiting": "Intezaar mein leads",
"Leads whose salesman did not prove he called the customer back. Move each one to another salesman, keep it with a new deadline, or excuse it. Nothing moves until you approve.": "Wo leads jinke salesman ne customer ko wapas call karne ka proof nahi diya. Har ek ko dusre salesman ko move karo, naye deadline ke saath rakho, ya maaf kar do. Tumhare approve karne tak kuch nahi badlega.",
