"That would make a loop: this person cannot report to someone who reports to them": "Isse loop ban jayega: ye person us ko report nahi kar sakta jo khud ise report karta hai",
"The 14-day clock from delivery": "Delivery se 14 din ki clock",
"The 6 digits from your authenticator app. Each code works once.": "Authenticator app ke 6 digits. Har code sirf ek baar chalta hai.",
"The 8 must-haves first, then 2 for every mark, then the rest in shot order. At most 40 here; the full shoot goes to the Drive folder. Never photograph a paper, a screen with a name, or a chassis number.": "Pehle 8 must-haves, phir har mark ke 2, phir baaki shot order mein. Yahan maximum 40; poori shoot Drive folder mein jaati hai. Kabhi paper, naam wali screen ya chassis number ki photo mat lo.",
"the AI says look first · {} to look at": "AI kehta hai pehle dekho · {} dekhne hain",
"The app, and Claude for the ones it cannot read": "App, aur jo wo padh nahi paata unke liye Claude",
"The app, for free": "App, free mein",
"The approver has": "Approver ke paas hai",
"The audit log shows who looked at what, and when.": "Audit log dikhata hai kisne kya aur kab dekha.",
"The balance on the opening date; the cashbook builds on it.": "Opening date ka balance; cashbook isi pe banta hai.",
"The bank account it was paid from. Leave empty for cash or on credit.": "Jis bank account se paid hua. Cash ya udhaar ke liye khali chhodo.",
"The bank account the money left. Leave empty for cash.": "Jis bank account se paisa gaya. Cash ke liye khali chhodo.",
