"The car": "Gaadi",
"the car": "gaadi",
"The car goes back to available. A refund can be recorded now.": "Gaadi wapas available ho jaati hai. Ab refund record kar sakte ho.",
"The car-by-car list is for people who can open Deals. The totals above still count every delivered car.": "Gaadi-wari list unke liye hai jo Deals khol sakte hain. Upar ke totals mein har delivered gaadi gini jaati hai.",
"the cashbook, ledger, GST and TCS": "cashbook, ledger, GST aur TCS",
"The chat with Anita and any call recording show here once the lead is yours.": "Anita ke saath chat aur call recording yahan tab dikhegi jab lead tumhari ho.",
"The checked screenshots could not load.": "Checked screenshots load nahi hue.",
"The chosen screenshot": "Chuna hua screenshot",
"The claim clock is not answering.": "Claim clock jawab nahi de rahi.",
"The Claude suggestions are switched off. Switch them on first (the bank narrations would be sent to Anthropic).": "Claude suggestions off hain. Pehle on karo (bank narrations Anthropic ko bheji jaayengi).",
"The clocks run only while the showroom is open. This also moves the evening roll-call, the night queue and the call-back time customers are told.": "Clocks sirf showroom khula hone par chalti hain. Isse evening roll-call, night queue aur customers ko bataya gaya call-back time bhi badal jaata hai.",
"The code is 6 digits.": "Code 6 digits ka hota hai.",
"The daily report 30 minutes after closing, the weekly one on Monday morning, the monthly one on the last day of the month.": "Daily report closing ke 30 minutes baad, weekly Monday subah, monthly mahine ke last din.",
"The dashboard only reads the lead engine's database. It never writes to it, and nothing leaves this server.": "Dashboard sirf lead engine ka database padhta hai. Kabhi likhta nahi, aur is server se kuch bahar nahi jaata.",
"The day the money left. Leave it empty if you still owe it: it then waits under Payables instead of reaching the cashbook.": "Jis din paisa gaya. Agar abhi dena baaki hai to khali chhodo: tab ye cashbook mein nahi jaata, Payables mein wait karta hai.",
"The demo has no sign-in. Use the buttons at the top to switch between owner, manager and salesman.": "Demo mein login nahi hai. Owner, manager aur salesman ke beech badalne ke liye upar ke buttons use karo.",
"The draft and its photos and scans are deleted.": "Draft aur uski photos aur scans delete ho jaate hain.",
"The engine has not listed the bands.": "Engine ne bands list nahi kiye.",
"The engine has not listed the salesmen.": "Engine ne salesmen list nahi kiye.",
"The engine name must match the name the lead engine uses, letter for letter.": "Engine name bilkul wahi hona chahiye jo lead engine use karta hai, har letter same.",
"The file could not be read.": "File padhi nahi ja saki.",
"The file has headings but no transactions. Check the dates you chose when you downloaded it.": "File mein headings hain par transactions nahi. Download karte waqt jo dates chuni thi wo check karo.",
"The file is empty": "File khali hai",
