"The file is larger than 15 MB. Split it into shorter periods.": "File 15 MB se badi hai. Chhote periods mein split karo.",
"The file looks like it belongs to the account ending {}, but you chose {}. Lines would be filed under the wrong account.": "File {} pe khatam hone wale account ki lagti hai, par tumne {} chuna. Lines galat account mein jaayengi.",
"The file mentions an account ending {}, but you chose {}. Check before you import.": "File mein {} pe khatam hone wale account ka zikr hai, par tumne {} chuna. Import se pehle check karo.",
