"The lead closes as sold. Add the token and papers on the lead's page.": "Lead sold ke roop mein close ho jaati hai. Token aur papers lead ke page pe add karo.",
"The lead engine is not answering, so the conversation cannot show right now. Try again in a minute.": "Lead engine jawab nahi de raha, isliye conversation abhi nahi dikh sakti. Ek minute mein phir se try karo.",
"The lead engine is not answering, so this call is not recorded. Calling the customer comes first. Call anyway?": "Lead engine jawab nahi de raha, isliye ye call record nahi hogi. Customer ko call karna pehle hai. Phir bhi call karo?",
"The lead engine is not answering.": "Lead engine jawab nahi de raha.",
"The lead engine is not answering. Nothing was moved.": "Lead engine jawab nahi de raha. Kuch move nahi hua.",
"The lead engine is not answering. Send still saves it, and it goes to whoever's turn it is as soon as the engine is back.": "Lead engine jawab nahi de raha. Send phir bhi save kar leta hai, aur engine wapas aate hi jiski baari hai use mil jaata hai.",
"The lead engine is not answering. Try again in a minute.": "Lead engine jawab nahi de raha. Ek minute mein phir se try karo.",
"The lead engine refused it.": "Lead engine ne mana kar diya.",
"The lead engine's database cannot be read from this dashboard right now, so website visits cannot be counted. Inquiries already mirrored are not affected.": "Lead engine ka database abhi is dashboard se padha nahi ja sakta, isliye website visits gine nahi ja sakte. Jo inquiries pehle mirror ho chuki hain unpe asar nahi.",
"The lead engine's figures have not reached this dashboard yet, so nothing can be listed.": "Lead engine ke figures abhi is dashboard tak nahi pahunche, isliye kuch list nahi ho sakta.",
"The line is part of the format until the car is saved": "Gaadi save hone tak ye line format ka hissa hai",
