"The page works fully without this. It is off until the owner switches it on.": "Page iske bina bhi poora chalta hai. Jab tak owner on nahi karta ye off hai.",
"The pages stay the same.": "Pages wahi rehte hain.",
"The pages stay the same. They are signed out and sign in again with the new role. This is logged.": "Pages wahi rehte hain. Wo logout ho jaate hain aur nayi role ke saath phir login karte hain. Ye log hota hai.",
"The photo is attached as the receipt when you save.": "Save karte waqt photo receipt ke roop mein attach hoti hai.",
"The photo is still attached as the receipt when you save.": "Save karte waqt photo ab bhi receipt ke roop mein attach rehti hai.",
