"The read-back": "Read-back",
"The reader works on photos (JPG, PNG or WebP). Fill the form by hand and attach this file as the receipt after saving.": "Reader photos pe chalta hai (JPG, PNG ya WebP). Form haath se bharo aur save ke baad ye file receipt ke roop mein attach karo.",
"The report": "Report",
"The reports could not load.": "Reports load nahi hue.",
"The rest of the clean ones are approved by themselves. 100 = check every one.": "Baaki saaf wale khud approve ho jaate hain. 100 = har ek check karo.",
"The reveal is written to the audit log with your name.": "Reveal tumhare naam ke saath audit log mein likha jaata hai.",
