"the rotation": "rotation",
"The RTO desk can upload transfer papers (RC, forms, NOC, insurance, PUC) to cars, deals and RTO cases only.": "RTO desk sirf cars, deals aur RTO cases pe transfer papers (RC, forms, NOC, insurance, PUC) upload kar sakta hai.",
"The rules found nothing to flag in this period.": "Rules ko is period mein flag karne layak kuch nahi mila.",
"The rules found nothing to flag. Nice.": "Rules ko flag karne layak kuch nahi mila. Badhiya.",
"The rupees this costs you, or could earn you, if it is fixed. It is an estimate, not a loss already booked.": "Ye woh rupaye hain jo iske fix na hone se tumhe lagte hain, ya fix hone pe mil sakte hain. Ye estimate hai, book hua loss nahi.",
"the salesman": "salesman",
