"The workbook was not imported": "Workbook import nahi hui",
"the yard and workshop: where each car is, checklists with photos, inspections. No prices or money": "yard aur workshop: har gaadi kahan hai, photos ke saath checklists, inspections. Koi prices ya paisa nahi",
