"there": "wahan",
"There is no failed website job for this car.": "Is gaadi ke liye koi failed website job nahi hai.",
"These cars are on the website but not in the Desk yet. If this car is one of them, pick it: it is linked, not listed twice, and its website details fill in here.": "Ye gaadiyan website pe hain par Desk mein abhi nahi. Agar ye gaadi inme se ek hai to ise chuno: ye link ho jaayegi, do baar list nahi hogi, aur iski website details yahan bhar jaayengi.",
"These {} leads go": "Ye {} leads jaayengi",
