"They are kept for history, but no longer matched or offered in the lists. You can show them again.": "Ye history ke liye rakhe jaate hain, par ab match nahi hote aur lists mein nahi aate. Phir se dikha sakte ho.",
"They are saved in People, so next time they are matched by name.": "Ye People mein save ho jaate hain, isliye agli baar naam se match honge.",
"They are signed out and sign in again with the new role. This is logged.": "Wo logout ho jaate hain aur nayi role ke saath phir login karte hain. Ye log hota hai.",
"They are signed out on their next click.": "Wo agle click pe logout ho jaate hain.",
"They get a one-time password and must change it at first sign-in. Nobody starts with money access.": "Unhe one-time password milta hai aur pehle login pe badalna padta hai. Koi bhi money access ke saath shuru nahi karta.",
