"You can remove your own message within 15 minutes.": "Apna message aap 15 minute ke andar hata sakte ho.",
"You can reset anyone else's from Users and access. Yours is reset from the server shell with create_user.py --reset-totp.": "Dusron ka aap Users aur access se reset kar sakte ho. Aapka server shell se create_user.py --reset-totp ke zariye reset hota hai.",
"You can see only your own to-dos.": "Aap sirf apne to-dos dekh sakte ho.",
"You can see the timers but not change the rules": "Aap timers dekh sakte ho par rules badal nahi sakte",
"You can see this lead. Only the salesman, the manager and the partners can act on it.": "Aap yeh lead dekh sakte ho. Is par kaam sirf salesman, manager aur partners kar sakte hain.",
"You can stop at any time. Your answers are saved as you go.": "Aap kabhi bhi ruk sakte ho. Aapke jawab apne-aap save hote jaate hain.",
"You cannot add documents here.": "Aap yahan documents add nahi kar sakte.",
"You cannot add documents to this record.": "Aap is record mein documents add nahi kar sakte.",
"You cannot change this column": "Aap yeh column nahi badal sakte",
"You cannot change this role.": "Aap yeh role nahi badal sakte.",
"You cannot change your own access.": "Aap apna khud ka access nahi badal sakte.",
"You cannot change your own role or disable yourself": "Aap apna role nahi badal sakte aur khud ko disable nahi kar sakte",
"You cannot claim new leads until it is in.": "Jab tak yeh nahi bharte, nayi leads claim nahi kar sakte.",
"You cannot decide your own request. Another manager or an owner does.": "Aap apni request ka faisla nahi kar sakte. Koi dusra manager ya owner karega.",
"You cannot delete this document.": "Aap yeh document delete nahi kar sakte.",
"You cannot export the P&L.": "Aap P&L export nahi kar sakte.",
"You cannot export this table.": "Aap yeh table export nahi kar sakte.",
"You cannot give this.": "Yeh aap nahi de sakte.",
"You cannot open this grid.": "Aap yeh grid nahi khol sakte.",
"You cannot open this paper.": "Aap yeh kaagaz nahi khol sakte.",
"You did not pick up": "Aapne call nahi uthaya",
"You do not have access to this.": "Aapko iska access nahi hai.",
"You entered": "Aapne bhara",
"You get 10 minutes to claim a lead. A notification tells you the moment it is yours. It never shows the customer's name or number.": "Lead claim karne ke liye 10 minute milte hain. Aapki hote hi notification bata deta hai. Usmein customer ka naam ya number kabhi nahi dikhta.",
"You have access to it. Money pages lock after 30 idle minutes; you stay signed in. Set up two-factor below; it takes about a minute.": "Aapke paas iska access hai. Paise wale pages 30 minute idle rehne par lock ho jaate hain; aap logged in rehte ho. Neeche two-factor set up karo; isme kareeb ek minute lagta hai.",
"You have access to it. Money pages lock after 30 idle minutes; you stay signed in. Type the 6 digits from your app below to open them.": "Aapke paas iska access hai. Paise wale pages 30 minute idle rehne par lock ho jaate hain; aap logged in rehte ho. Inhe kholne ke liye neeche app ka 6 digits ka code likho.",
"You marked this done yourself. Someone else has to check it.": "Isse aapne khud 'Ho gaya' kiya hai. Check kisi aur ko karna hoga.",
"You may hand on only the money access you hold yourself.": "Jo paise ka access aapke paas hai, sirf wahi aap dusron ko de sakte ho.",
"You signed out, so your access is waiting for approval again. Ask the owner to approve it.": "Aapne logout kiya, isliye aapka access phir se approval ke intezaar mein hai. the owner se approve karne ko kaho.",
"You spoke to the customer or replied to them.": "Aapne customer se baat ki ya unhe reply kiya.",
"You stay signed in on your phone for 30 days. Only the money pages lock, and your 6-digit code opens them again. The timer is in the top bar.": "Aap phone par 30 din tak logged in rehte ho. Sirf paise wale pages lock hote hain, aur aapka 6 digits ka code unhe phir khol deta hai. Timer upar ki bar mein hai.",
"You stay signed in. Money pages lock after {} idle minutes and open again with your 6-digit code.": "Aap logged in rehoge. {} minute kuch na karne par paise wale pages lock ho jaate hain aur 6 digits ke code se phir khulte hain.",
"You will get a ping for new leads, mentions and answers from Ask Claude.": "Nayi leads, mentions aur Ask Claude ke jawab par aapko ping milega.",
"Your books are locked until you enter your two-factor code.": "Jab tak aap two-factor code nahi daalte, aapki books locked hain.",
"Your browser cannot play this recording.": "Aapka browser yeh recording nahi chala sakta.",
"Your call timers, how you are doing, and your warnings. Never money.": "Aapke call timers, aap kaisa kar rahe ho, aur aapki warnings. Paise ki baat kabhi nahi.",
"Your chat with Claude": "Claude ke saath aapki chat",
"Your explanation": "Aapki explanation",
"Your explanation:": "Aapki explanation:",
"Your first statement will be listed here.": "Aapka pehla statement yahan dikhega.",
"Your full name": "Aapka poora naam",
"Your latest answers are not saved yet. Check the connection and try again.": "Aapke latest jawab abhi save nahi hue. Connection check karo aur phir se try karo.",
"Your leads first, then leads in your price band you can grab. Claim within 10 minutes.": "Pehle aapki leads, phir aapke price band ki woh leads jo aap le sakte ho. 10 minute mein claim karo.",
"Your leads, drives, follow-ups and deliveries.": "Aapki leads, drives, follow-ups aur deliveries.",
