"{}. Followers, website interactions and the channels that bring inquiries.": "{}. Followers, website par halchal aur inquiry laane wale channels.",
"{}. It stays in the ledger, marked excused, and stops counting.": "{}. Yeh ledger mein rahegi, maaf ka nishaan lagega, aur ginti mein nahi aayegi.",
"{}. Loans we arranged, policies we sold, and who bought a car from us without either.": "{}. Humare karaye loans, bechi policies, aur jinhone gaadi li par inmein se kuch nahi liya.",
"{}. Mirrored from the lead engine every minute. The engine is never written to.": "{}. Lead engine se har minute copy hota hai. Engine mein kabhi kuch badla nahi jaata.",
"{}. Missed means a lead nobody claimed in {} minutes.": "{}. Missed ka matlab woh lead jise {} minute mein kisi ne claim nahi kiya.",
