"{}. Pick it again or untick Already on the website.": "{}. Phir se chuno ya 'Website par pehle se hai' ka tick hata do.",
"{}. Profit is what is left after the car, its costs, GST on margin and the salesman's incentive.": "{}. Profit woh hai jo gaadi, uske costs, margin par GST aur salesman ke incentive ke baad bachta hai.",
